WITH lines AS (SELECT id, service, host, level, latency_ms, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS attr_key, attr_value), valid AS (SELECT id, host, level, latency_ms, attr_key, attr_value, CASE WHEN attr_key IN ('region', 'trace') THEN 'Core' ELSE 'Other' END attr_key_group, COALESCE(attr_key, 'NONE') resolved_attr_key FROM lines WHERE service = 'auth'), matched_keys AS (SELECT host, level FROM valid EXCEPT ALL SELECT host, level FROM app_logs WHERE service IN ('search', 'billing', 'checkout')), verified AS (SELECT s.* FROM valid s INNER JOIN matched_keys k ON s.host = k.host AND s.level = k.level), valid_app_logs AS (SELECT id, attr_key, attr_key_group, resolved_attr_key, CASE WHEN level IN ('DEBUG', 'INFO') THEN 'Tier 1' ELSE 'Other' END level_group, LOWER(host) host_lower FROM verified WHERE attr_key IS DISTINCT FROM 'region') SELECT attr_key, COUNT(*) AS row_count, COUNT(CASE WHEN attr_key = 'version' THEN 1 END) AS version_count, COUNT(*) AS num_rows, COUNT(CASE WHEN attr_key = 'region' THEN 1 END) AS region_count FROM valid_app_logs GROUP BY attr_key ORDER BY version_count;
